using System;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class DungeonInteractionValidation {
 public static List<DungeonInteractionSettings> Profiles(DungeonMapSettings map){var list=new List<DungeonInteractionSettings>();var queue=new Queue<DungeonInteractionSettings>();if(map.entities!=null)foreach(var e in map.entities.objects)if(e!=null&&e.interaction!=null)queue.Enqueue(e.interaction);foreach(var b in map.legacyInteractions??new DungeonLegacyInteractionBinding[0])if(b!=null&&b.profile!=null)queue.Enqueue(b.profile);while(queue.Count>0){var p=queue.Dequeue();if(p==null||list.Contains(p))continue;list.Add(p);foreach(var a in p.actions)if(a!=null&&a.eventProfile!=null)queue.Enqueue(a.eventProfile);}return list;}
 public static DungeonMapEntity Entity(DungeonMapSettings map,string id){return map.entities?.objects.Find(e=>e!=null&&e.id==id);}
 static bool Legacy(DungeonMapSettings map,string id,bool door){if(!map.includeLegacyObjects||map.disabledLegacyObjects.Contains(id))return false;if(door)return id=="legacy.exit"||id=="refuge.exit"||id=="corridor.door";return RefugeSettings.Current!=null&&Array.Exists(RefugeSettings.Current.nodes,n=>n.id==id);}
 static bool KnownItem(string id){var inventory=Resources.Load<CombatInventorySettings>("Combat/CombatInventorySettings");var player=Resources.Load<PlayerCharacterSettings>("Combat/PlayerCharacterSettings");return inventory!=null&&Array.Exists(inventory.items,i=>i!=null&&i.id==id)||player!=null&&Array.Exists(player.equipment,i=>i!=null&&i.id==id);}
 public static List<string> Validate(DungeonMapSettings map){var errors=new List<string>();var profiles=Profiles(map);var ids=new HashSet<string>();var eventIds=new HashSet<string>();foreach(var id in map.eventIds??new string[0])if(string.IsNullOrEmpty(id)||!eventIds.Add(id))errors.Add("ID de evento vacío o duplicado: "+id);foreach(var p in profiles){if(string.IsNullOrEmpty(p.id)||!ids.Add(p.id))errors.Add("ID de perfil vacío o duplicado: "+p.id);eventIds.Add(p.id);}
  var bindings=new HashSet<string>();foreach(var b in map.legacyInteractions??new DungeonLegacyInteractionBinding[0]){if(b==null||b.profile==null){errors.Add("Adaptador heredado sin perfil");continue;}if(!bindings.Add(b.targetId))errors.Add("Adaptador heredado duplicado: "+b.targetId);bool npc=map.includeLegacyObjects&&RefugeSettings.Current!=null&&Array.Exists(RefugeSettings.Current.npcs,n=>n.id==b.targetId);if(!npc&&!Legacy(map,b.targetId,true)&&!Legacy(map,b.targetId,false)&&b.targetId!="refuge.save")errors.Add("Destino heredado inexistente: "+b.targetId);}
  foreach(var p in profiles){var actionIds=new HashSet<string>();foreach(var a in p.actions){if(a==null){errors.Add(p.name+": acción nula");continue;}if(string.IsNullOrEmpty(a.id)||!actionIds.Add(a.id))errors.Add(p.name+": ID de acción vacío o duplicado");var e=Entity(map,a.targetId);switch(a.kind){
    case DungeonEventActionKind.OpenDoor:case DungeonEventActionKind.CloseDoor:if((e==null||e.kind!=DungeonEntityKind.Door)&&!Legacy(map,a.targetId,true))errors.Add(p.name+": puerta inexistente "+a.targetId);break;
    case DungeonEventActionKind.UnlockConnection:if((e==null||e.kind!=DungeonEntityKind.Door&&e.kind!=DungeonEntityKind.Teleport)&&!Legacy(map,a.targetId,true)&&!Legacy(map,a.targetId,false))errors.Add(p.name+": conexión inexistente "+a.targetId);break;
    case DungeonEventActionKind.SetSwitch:if(e==null||e.kind!=DungeonEntityKind.Switch)errors.Add(p.name+": interruptor inexistente "+a.targetId);break;
    case DungeonEventActionKind.Reward:if(!KnownItem(a.targetId)||a.quantity<1)errors.Add(p.name+": recompensa inválida "+a.targetId);break;
    case DungeonEventActionKind.CompleteEvent:if(!eventIds.Contains(a.targetId))errors.Add(p.name+": evento sin declarar "+a.targetId);break;
    case DungeonEventActionKind.RunEvent:if(a.eventProfile==null)errors.Add(p.name+": falta perfil narrativo");else if(Cycle(p,a.eventProfile,new HashSet<DungeonInteractionSettings>()))errors.Add(p.name+": ciclo de eventos");break;
    case DungeonEventActionKind.Dialogue:if(a.dialogue==null||a.dialogue.Length==0)errors.Add(p.name+": diálogo vacío");break;
   }}
   var all=new List<DungeonCondition>();foreach(var group in p.groups){if(group==null){errors.Add(p.name+": grupo nulo");continue;}if(group.join==DungeonConditionJoin.Any&&group.conditions.Count==0)errors.Add(p.name+": grupo OR vacío, imposible");foreach(var c in group.conditions){if(c==null){errors.Add(p.name+": condición nula");continue;}var source=c.sourceMap!=null?c.sourceMap:map;var e=Entity(source,c.targetId);switch(c.kind){
     case DungeonConditionKind.Item:if(!KnownItem(c.targetId)||c.quantity<1)errors.Add(p.name+": objeto de condición inválido "+c.targetId);break;
     case DungeonConditionKind.SwitchActive:if(e==null||e.kind!=DungeonEntityKind.Switch)errors.Add(p.name+": condición sobre interruptor inexistente "+c.targetId);break;
     case DungeonConditionKind.EnemyDefeated:var r=source.regions??(source.includeLegacyObjects?DungeonRegionSettings.Current:null);if(r==null||!Array.Exists(r.placedEnemies,v=>v!=null&&v.id==c.targetId&&v.enabled))errors.Add(p.name+": enemigo de condición inexistente/desactivado "+c.targetId);break;
     case DungeonConditionKind.EventCompleted:var available=new HashSet<string>(source.eventIds??new string[0]);foreach(var other in Profiles(source))available.Add(other.id);if(!available.Contains(c.targetId))errors.Add(p.name+": evento de condición inexistente "+c.targetId);break;
     case DungeonConditionKind.HackUnlocked:var h=PlayerHackCatalog.Current?.Find(c.targetId);if(h==null)errors.Add(p.name+": HACK inexistente "+c.targetId);else if(!c.negate&&(!h.available||h.ImplementationType==null||h.minimumLevel>PlayerLevelSettings.Current.maximumLevel&&h.unlockMode==HackUnlockMode.PlayerLevel))errors.Add(p.name+": HACK imposible/no funcional "+c.targetId);break;
    }}if(group.join==DungeonConditionJoin.All){Contradictions(group.conditions,errors,p.name);if(p.join==DungeonConditionJoin.All)all.AddRange(group.conditions);}}
   Contradictions(all,errors,p.name);
  }
  if(map.entities!=null)foreach(var entity in map.entities.objects)if(entity!=null&&entity.kind==DungeonEntityKind.Switch&&!entity.switchInitiallyActive&&entity.interaction!=null&&entity.interaction.join==DungeonConditionJoin.All){foreach(var group in entity.interaction.groups)if(group.join==DungeonConditionJoin.All&&group.conditions.Exists(c=>c!=null&&!c.negate&&c.kind==DungeonConditionKind.SwitchActive&&c.targetId==entity.id&&(c.sourceMap==null||c.sourceMap==map))&&!profiles.Exists(p=>p!=entity.interaction&&p.actions.Exists(a=>a.kind==DungeonEventActionKind.SetSwitch&&a.targetId==entity.id&&a.value)))errors.Add(entity.id+": interruptor exige su propia activación sin fuente externa");}
  return new List<string>(new HashSet<string>(errors));
 }
 static void Contradictions(List<DungeonCondition> terms,List<string> errors,string name){for(int i=0;i<terms.Count;i++)for(int j=i+1;j<terms.Count;j++){var a=terms[i];var b=terms[j];if(a!=null&&b!=null&&a.kind==b.kind&&a.sourceMap==b.sourceMap&&a.targetId==b.targetId&&a.quantity==b.quantity&&a.negate!=b.negate)errors.Add(name+": AND contradictorio/imposible "+a.targetId);}}
 static bool Cycle(DungeonInteractionSettings root,DungeonInteractionSettings node,HashSet<DungeonInteractionSettings> seen){if(node==root)return true;if(!seen.Add(node))return false;foreach(var a in node.actions)if(a!=null&&a.kind==DungeonEventActionKind.RunEvent&&a.eventProfile!=null&&Cycle(root,a.eventProfile,seen))return true;return false;}
}
[CustomEditor(typeof(DungeonInteractionSettings))] public sealed class DungeonInteractionSettingsEditor:Editor {
 DungeonMapSettings context;
 public override void OnInspectorGUI(){DrawDefaultInspector();var p=(DungeonInteractionSettings)target;EditorGUILayout.HelpBox("Grupos combinables AND/OR. ID y acciones son persistentes: no cambiar/reordenar eventos publicados en una ejecución pendiente. Las recompensas tienen recibo propio y no se repiten.",MessageType.Info);if(GUILayout.Button("Añadir acción con ID nuevo")){Undo.RecordObject(p,"Añadir acción");p.actions.Add(new DungeonEventAction());EditorUtility.SetDirty(p);}context=(DungeonMapSettings)EditorGUILayout.ObjectField("Mapa de validación",context!=null?context:DungeonMapSettings.Current,typeof(DungeonMapSettings),false);if(context!=null&&GUILayout.Button("Validar interacciones del mapa"))foreach(var error in DungeonInteractionValidation.Validate(context))Debug.LogWarning(error,context);}
}
